import "./.next/types/routes.d.ts";

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.

import { headers } from 'next/headers'
import { after } from 'next/server'

import { logPageView } from '@/lib/analytics'

function firstForwardedIp(value: string | null): string | undefined {
  return value?.split(',')[0]?.trim() || undefined
}

export default async function WelcomeMessage() {
  const requestHeaders = await headers()
  const pageView = {
    path: '/',
    referrer: requestHeaders.get('referer') ?? undefined,
    userAgent: requestHeaders.get('user-agent') ?? 'unknown',
    ipAddress:
      firstForwardedIp(requestHeaders.get('x-forwarded-for')) ??
      requestHeaders.get('x-real-ip') ??
      undefined,
    viewedAt: new Date().toISOString(),
  }

  after(() =>
    logPageView(pageView).catch((error: unknown) => {
      console.error('Failed to log page view', error)
    }),
  )

  return (
    <section>
      <h1>Welcome</h1>
      <p>Thanks for visiting. Your page view is being recorded.</p>
    </section>
  )
}

export type PageViewEvent = {
  path: string
  referrer?: string
  userAgent: string
  ipAddress?: string
  viewedAt: string
}

export async function logPageView(event: PageViewEvent): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    console.info('analytics.page_view', event)
    return
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(process.env.ANALYTICS_API_KEY
        ? { Authorization: `Bearer ${process.env.ANALYTICS_API_KEY}` }
        : {}),
    },
    body: JSON.stringify({
      type: 'page_view',
      ...event,
    }),
    cache: 'no-store',
  })

  if (!response.ok) {
    throw new Error(`Analytics request failed with status ${response.status}`)
  }
}

import WelcomeMessage from './_components/welcome-message'

